function flightMatchesAdvanced(f){const a=countryKey(flightCountry(f,'origin')),b=countryKey(flightCountry(f,'destination'));return (!flightState.type||flightCategory(f)===flightState.type)&&(!flightState.country||b===flightState.country)&&(!flightState.origin||f.origin===flightState.origin)&&(!flightState.destination||f.destination===flightState.destination)&&(flightState.type!=='international'||flightState.scope==='all'||(flightState.scope==='outbound'?a==='brasil':flightState.scope==='inbound'?b==='brasil':a!=='brasil'&&b!=='brasil'))}
function filteredFlightRows(){const q=norm(flightState.q);return aviation.flights.filter(f=>(!flightState.carrier||airlineKey(f.carrier)===flightState.carrier)&&(!flightState.bridge||isBridge(f))&&(!flightState.year||(flightState.year==='unknown'?!f.year:String(f.year)===flightState.year))&&q.split(/\s+/).every(term=>norm([f.origin,f.destination,f.originCity,f.destinationCity,f.originCountry,f.destinationCountry,f.carrier,f.code,f.year].join(' ')).includes(term))&&flightMatchesAdvanced(f)&&(!flightState.cityKey||countryKey(flightCountry(f,'destination'))+'|'+norm(f.destinationCity)===flightState.cityKey)).sort((a,b)=>{if(flightState.sort==='route')return (a.origin+' '+a.destination).localeCompare(b.origin+' '+b.destination);if(!a.year||!b.year)return a.year?-1:b.year?1:0;const diff=a.year-b.year;if(diff)return flightState.sort==='oldest'?diff:-diff;const date=f=>f.dayMonth?Number(f.dayMonth.slice(3))*32+Number(f.dayMonth.slice(0,2)):null;const da=date(a),db=date(b);if(da===null||db===null)return da===null?(db===null?0:1):-1;return flightState.sort==='oldest'?da-db:db-da})}
function advancedFlightControls(){const countries=[...new Map(aviation.flights.map(f=>{const c=flightCountry(f,'destination');return [countryKey(c),c]}).filter(([k])=>k)).entries()].sort((a,b)=>a[1].localeCompare(b[1],'pt'));const airportOptions=side=>[...new Set(aviation.flights.map(f=>f[side]).filter(Boolean))].sort().map(code=>`<option value="${esc(code)}">${esc(code)} · ${esc(aviationAirport(code)?.city||aviation.flights.find(f=>f[side]===code)?.[side+'City']||'Aeroporto')}</option>`).join('');return `<div class="flight-filter-grid"><label class="flight-search-field">BUSCAR<input id="flightSearch" type="search" placeholder="Cidade, aeroporto, companhia ou número do voo"></label><label>TIPO DE VOO<select id="flightType"><option value="">Todos os voos</option><option value="domestic">Nacionais · Brasil</option><option value="international">Internacionais</option><option value="bridge">São Paulo ↔ Rio</option></select></label><label>COMPANHIA<select id="flightCarrier"><option value="">Todas as companhias</option>${[...new Set(aviation.flights.map(f=>airlineKey(f.carrier)))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>ANO<select id="flightYear"><option value="">Todos os anos</option>${[...new Set(aviation.flights.map(f=>f.year).filter(Boolean))].sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('')}<option value="unknown">Ano não informado</option></select></label><label>PAÍS DE DESTINO<select id="flightCountry"><option value="">Todos os países</option>${countries.map(([key,c])=>`<option value="${esc(key)}">${esc(c)}</option>`).join('')}</select></label><label>SAÍDA DE<select id="flightOrigin"><option value="">Qualquer origem</option>${airportOptions('origin')}</select></label><label>CHEGADA EM<select id="flightDestination"><option value="">Qualquer destino</option>${airportOptions('destination')}</select></label><label id="flightScopeLabel" hidden>TRAJETO INTERNACIONAL<select id="flightScope"><option value="all">Todos os internacionais</option><option value="outbound">Saindo do Brasil</option><option value="inbound">Voltando ao Brasil</option><option value="abroad">Entre outros países</option></select></label></div><div class="flight-filter-bottom"><p id="flightFilterStatus" role="status" aria-live="polite">Todos os voos</p><label class="flight-sort-field">ORDENAR VOOS<select id="flightSort"><option value="newest">Mais recentes</option><option value="oldest">Mais antigos</option><option value="route">Origem e destino</option></select></label><button id="flightClear" type="button">Limpar filtros</button></div><div class="flight-active-filters" id="flightActiveFilters"></div>`}
function renderFlights(){renderFlightList();const fs=filteredFlightRows(),routes=new Map(),countries=new Set(),cities=new Set();let mins=0,covered=0,estimated=false;for(const f of fs){const key=f.origin+'|'+f.destination;const row=routes.get(key)||{origin:f.origin,destination:f.destination,originCity:f.originCity,destinationCity:f.destinationCity,count:0};row.count++;routes.set(key,row);const c=flightCountry(f,'destination');if(c)countries.add(countryKey(c));if(f.destinationCity)cities.add(countryKey(c)+'|'+norm(f.destinationCity));const m=aviationDuration(f);if(m!==null){mins+=m;covered++;if(!(f.minutes>0)||/estim/i.test(f.minutesKind))estimated=true}}const description=flightState.bridge?'Ponte aérea São Paulo ↔ Rio':flightState.type==='domestic'?'Voos dentro do Brasil':flightState.type==='international'?{outbound:'Voos internacionais saindo do Brasil',inbound:'Voos internacionais voltando ao Brasil',abroad:'Voos internacionais entre outros países',all:'Todos os voos internacionais'}[flightState.scope]:'Voos selecionados';$('#flightSummary').innerHTML=`<p class="sr-only">${description}</p><div class="flight-summary-stats">${[[fs.length,'voos','flights'],[routes.size,'percursos','routes'],[countries.size,'países de destino','countries'],[cities.size,'cidades de destino','cities'],[covered?num(mins/60)+'h':'—',estimated?'tempo · inclui estimativas':'tempo de voo','hours']].map(([n,l,key])=>`<button data-flight-pane="${key}" aria-expanded="${flightState.pane===key}" aria-controls="flightListPanel" class="${flightState.pane===key?'is-active':''}"><strong>${n}</strong><span>${l}</span></button>`).join('')}</div>${covered<fs.length?`<p class="flight-summary-note">Duração disponível para ${covered} de ${fs.length} voos.</p>`:''}`;renderFlightPane(fs,routes);$('#flightScopeLabel').hidden=flightState.type!=='international';syncFlightControls();document.querySelectorAll('[data-flight-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.flightKind===flightState.type)))}
function renderFlightPane(fs,routes){const pane=flightState.pane;$('#flightListPanel').hidden=!pane;$('#flightCount').hidden=pane!=='flights';$('#flightGrid').hidden=pane!=='flights';$('#flightMore').parentElement.hidden=pane!=='flights';$('#flightPaneGroups').hidden=!pane||pane==='flights';$('#flightPaneHeader').hidden=!pane;if(!pane)return;const names={flights:'Voos',routes:'Percursos',countries:'Países de destino',cities:'Cidades de destino',hours:'Tempo de voo'};$('#flightPaneHeader').innerHTML=`${flightState.cityKey?'<button id="clearCityDrill">Todas as cidades ×</button>':''}<h3>${names[pane]}</h3><button id="flightPaneClose" aria-label="Recolher detalhes">Recolher ×</button>`;if($('#clearCityDrill'))$('#clearCityDrill').onclick=()=>{flightState.cityKey='';renderFlights()};$('#flightPaneClose').onclick=()=>{flightState.pane=null;renderFlights()};if(pane==='flights')return;const target=$('#flightPaneGroups');target.className='flight-pane-groups '+(pane==='hours'?'duration-groups':'');if(pane==='routes'){target.innerHTML=[...routes.values()].sort((a,b)=>b.count-a.count||a.origin.localeCompare(b.origin)).map(r=>`<button class="explore-route-card" data-summary-origin="${esc(r.origin)}" data-summary-destination="${esc(r.destination)}"><span class="route-trace"><b>${esc(r.origin)}</b><i></i>${icon('plane')}<i></i><b>${esc(r.destination)}</b></span><span class="route-city-label">${esc(r.originCity)} → ${esc(r.destinationCity)}</span><span class="explore-card-footer"><strong>${r.count} ${r.count===1?'voo':'voos'}</strong><span>Explorar ${icon('arrow')}</span></span></button>`).join('');}else if(pane==='countries'||pane==='cities'){const groups=new Map();for(const f of fs){const c=flightCountry(f,'destination'),city=f.destinationCity;if(pane==='countries'&&!c||pane==='cities'&&!city)continue;const key=pane==='countries'?countryKey(c):countryKey(c)+'|'+norm(city);const g=groups.get(key)||{name:pane==='countries'?c:city,country:c,count:0,airports:new Set()};g.count++;if(f.destination)g.airports.add(f.destination);groups.set(key,g)}target.innerHTML=[...groups.entries()].sort((a,b)=>b[1].count-a[1].count||a[1].name.localeCompare(b[1].name,'pt')).map(([key,g])=>{const known=countries.find(c=>countryKey(c.name)===countryKey(g.country)),flag=known&&countryCodes[known.iso];return `<button class="destination-explore-card" data-summary-${pane==='countries'?'country':'city'}="${esc(key)}"><span class="destination-emblem">${pane==='countries'&&flag?`<img src="assets/flags/${flag}.svg" alt="">`:icon(pane==='countries'?'globe':'pin')}</span><strong>${esc(g.name)}</strong><small>${pane==='cities'?esc(g.country)+' · ':''}${esc([...g.airports].sort().join(' · '))}</small><span class="explore-card-footer"><strong>${g.count} ${pane==='cities'?'chegadas':g.count===1?'voo':'voos'}</strong><span>Explorar ${icon('arrow')}</span></span></button>`}).join('');}else if(pane==='hours'){const groups=new Map();let total=0,covered=0;for(const f of fs){const m=aviationDuration(f);if(m===null)continue;covered++;total+=m;const key=airlineKey(f.carrier),g=groups.get(key)||{minutes:0,count:0,estimated:false};g.minutes+=m;g.count++;g.estimated||=!(f.minutes>0)||/estim/i.test(f.minutesKind);groups.set(key,g)}target.innerHTML=`<p class="duration-caption">Tempo por companhia · duração disponível em ${covered} de ${fs.length} voos. As barras mostram a participação no tempo total deste recorte.</p>`+[...groups.entries()].sort((a,b)=>b[1].minutes-a[1].minutes).map(([name,g])=>`<article class="duration-row"><div><strong>${esc(name)}</strong><span>${Math.floor(g.minutes/60)}h ${String(g.minutes%60).padStart(2,'0')}min</span></div><div class="duration-track"><i style="width:${total?g.minutes/total*100:0}%"></i></div><small>${g.count} voos · ${total?Math.round(g.minutes/total*100):0}% do tempo${g.estimated?' · inclui estimativas':''}</small></article>`).join('');}if(!fs.length)target.innerHTML='<p class="gallery-empty">Nenhum resultado para os filtros selecionados.</p>';else if(!target.innerHTML)target.innerHTML='<p class="gallery-empty">Estes registros ainda não têm os dados necessários para esta visualização.</p>'}

function syncFlightControls(){for(const [id,key]of [['flightSearch','q'],['flightCarrier','carrier'],['flightYear','year'],['flightCountry','country'],['flightOrigin','origin'],['flightDestination','destination'],['flightSort','sort'],['flightScope','scope']])if($('#'+id).value!==flightState[key])$('#'+id).value=flightState[key];$('#flightType').value=flightState.bridge?'bridge':flightState.type;const labels={type:'Tipo',carrier:'Companhia',year:'Ano',country:'País',origin:'Saída',destination:'Chegada',scope:'Trajeto',q:'Busca',cityKey:'Cidade'},chips=[];if(flightState.bridge)chips.push(['type','São Paulo ↔ Rio']);else if(flightState.type)chips.push(['type',$('#flightType').selectedOptions[0].textContent]);for(const [id,key]of [['flightCarrier','carrier'],['flightYear','year'],['flightCountry','country'],['flightOrigin','origin'],['flightDestination','destination']])if(flightState[key])chips.push([key,$('#'+id).selectedOptions[0]?.textContent||flightState[key]]);if(flightState.type==='international'&&flightState.scope!=='all')chips.push(['scope',$('#flightScope').selectedOptions[0].textContent]);if(flightState.q)chips.push(['q',flightState.q]);if(flightState.cityKey)chips.push(['cityKey',flightState.cityKey.split('|').slice(1).join(' ')]);$('#flightActiveFilters').innerHTML=chips.map(([key,label])=>`<button type="button" data-clear-flight-filter="${key}" aria-label="Remover filtro ${esc(labels[key])}: ${esc(label)}">${esc(labels[key])}: ${esc(label)} <span aria-hidden="true">×</span></button>`).join('');$('#flightFilterStatus').textContent=chips.length?`${chips.length} ${chips.length===1?'filtro aplicado':'filtros combinados'} · ${filteredFlightRows().length} voos encontrados`:'Todos os voos';const shortcut=flightState.bridge?'bridge':flightState.type==='international'?'international':'all';document.querySelectorAll('[data-flight-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.flightFilter===(flightState.pane==='hours'&&!chips.length?'hours':shortcut))))}
function initializeAdvancedFlights(){const host=$('.flight-filters');host.innerHTML=advancedFlightControls();const advanced=document.createElement('details');advanced.className='advanced-flight-options';advanced.innerHTML='<summary>Mais filtros</summary><div class="flight-filter-grid advanced-flight-grid"></div>';const group=advanced.querySelector('div');for(const id of ['flightType','flightCountry','flightOrigin','flightDestination','flightScope'])group.append($('#'+id).closest('label'));host.querySelector('.flight-filter-grid').after(advanced);host.insertAdjacentHTML('afterend','<div id="flightSummary"></div>');const panel=document.createElement('div');panel.id='flightListPanel';panel.hidden=true;$('#flightGrid').before(panel);panel.innerHTML='<div id="flightPaneHeader" class="flight-pane-header" hidden></div><div id="flightPaneGroups" hidden></div>';panel.append($('#flightGrid'),$('#flightMore').parentElement);for(const [id,key]of [['flightCountry','country'],['flightOrigin','origin'],['flightDestination','destination'],['flightSort','sort'],['flightScope','scope'],['flightCarrier','carrier'],['flightYear','year']])$('#'+id).onchange=e=>{flightState[key]=e.target.value;flightState.limit=20;renderFlights()};$('#flightSearch').oninput=e=>{flightState.q=e.target.value;flightState.limit=20;renderFlights()};$('#flightType').onchange=e=>{flightState.bridge=e.target.value==='bridge';flightState.type=flightState.bridge?'domestic':e.target.value;flightState.scope='all';flightState.limit=20;renderFlights()};document.addEventListener('click',e=>{const pane=e.target.closest('[data-flight-pane]');if(pane){flightState.pane=pane.dataset.flightPane;renderFlights();return}const clear=e.target.closest('[data-clear-flight-filter]');if(clear){const key=clear.dataset.clearFlightFilter;if(key==='type'){flightState.type='';flightState.bridge=false;flightState.scope='all'}else flightState[key]=key==='scope'?'all':'';flightState.limit=20;renderFlights();return}const dest=e.target.closest('[data-summary-country],[data-summary-city]');if(dest){if(dest.dataset.summaryCountry)flightState.country=dest.dataset.summaryCountry;else flightState.cityKey=dest.dataset.summaryCity;flightState.pane='flights';flightState.limit=20;renderFlights();return}const route=e.target.closest('[data-summary-origin]');if(route){flightState.origin=route.dataset.summaryOrigin;flightState.destination=route.dataset.summaryDestination;flightState.pane='flights';flightState.limit=20;renderFlights();$('#flightListPanel').scrollIntoView({behavior:reduced?'auto':'smooth'})}});renderFlights()}

function showFlights(key='all',scroll=true){Object.assign(flightState,{q:'',carrier:'',bridge:key==='bridge',year:'',limit:20,type:key==='international'?'international':key==='bridge'?'domestic':'',scope:'all',country:'',origin:'',destination:'',sort:'newest',listOpen:false,pane:key==='hours'?'hours':'flights',cityKey:''});$('#flightCollection').hidden=false;$('#flightExplore').setAttribute('aria-expanded','true');$('#flightExplore').innerHTML='Recolher voos '+icon('arrow');renderFlights();if(scroll)$('#flightCollection').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'})}
function flightOnMap(id){const f=aviation.flights.find(f=>f.id===id);if(!f||!aviationHasRoute(f))return;manualView=true;selectedPlaceScope=null;focusedLeg=null;mapReturn=()=>$('#flightCollection').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});$('#mapBack').textContent='Voltar aos voos';$('#mapBack').hidden=false;stopPlayback(true);selectedTrip='';selectedFlight=id;$('#tripSelect').value='';$('#tripCurrentLabel').textContent=f.origin+' → '+f.destination;$('#tripBrowser').open=false;mapLayer='flights';$('#mapPlace').hidden=true;document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layer===mapLayer)));setRoutePlane(f,.5);syncRouteControls();update2d();update3d();pendingRouteFocus=true;focusRoute();$('#mapCaption').textContent=`${f.origin} → ${f.destination} · ${f.carrier||'Voo'}`;$('#explore').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'})}
function initializeFlights(){initializeAdvancedFlights();$('#flightExplore').onclick=()=>{const open=!$('#flightCollection').hidden;if(open){$('#flightCollection').hidden=true;$('#flightExplore').setAttribute('aria-expanded','false');$('#flightExplore').innerHTML='Ver voos '+icon('arrow')}else showFlights()};document.querySelectorAll('[data-flight-filter]').forEach(b=>b.onclick=()=>showFlights(b.dataset.flightFilter));$('#flightClear').onclick=()=>{const pane=flightState.pane;showFlights('all',false);flightState.pane=pane;renderFlights()};$('#flightMore').onclick=()=>{flightState.limit+=20;renderFlights()};document.addEventListener('click',e=>{const b=e.target.closest('[data-flight-map]');if(b){const d=$('#atlasDetail');if(d?.open)d.close();flightOnMap(b.dataset.flightMap)}})}
function initializeNavigation(){
const header=$('.preview-header'),links=[...document.querySelectorAll('.main-nav a')],sections=links.map(a=>$(a.hash)).filter(Boolean);
let clicked='',releaseTimer;
const activate=id=>links.forEach(a=>{if(a.hash==='#'+id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});
const measure=()=>{document.documentElement.style.setProperty('--atlas-nav-height',Math.ceil(header.getBoundingClientRect().height)+'px');document.documentElement.style.setProperty('--atlas-page-width',document.documentElement.clientWidth+'px')};
for(const id of ['stadiums','journeys','memories']){const section=$('#'+id);if(section){const divider=document.createElement('div');divider.className='atlas-section-transition';divider.setAttribute('aria-hidden','true');divider.innerHTML='<span class="atlas-transition-mist"></span>';section.before(divider)}}
const update=()=>{header.classList.toggle('is-compact',scrollY>100||(header.classList.contains('is-compact')&&scrollY>24));if(clicked){activate(clicked);return}const top=header.getBoundingClientRect().bottom+42;let active=sections[0]?.id;for(const section of sections)if(section.getBoundingClientRect().top<=top)active=section.id;if(scrollY>100&&innerHeight+scrollY>=document.documentElement.scrollHeight-2)active=sections.at(-1)?.id;activate(active)};
const schedule=()=>update();
const release=()=>{clicked='';clearTimeout(releaseTimer);schedule()};
const finishNavigation=()=>{if(clicked){const section=$('#'+clicked),offset=section.getBoundingClientRect().top-header.getBoundingClientRect().bottom-20;if(Math.abs(offset)>2)scrollBy({top:offset,behavior:'instant'})}release()};
const navSizeObserver=new ResizeObserver(()=>{measure();schedule()});navSizeObserver.observe(header);navSizeObserver.observe(document.documentElement);addEventListener('resize',measure,{passive:true});
addEventListener('scroll',()=>{schedule();if(clicked){clearTimeout(releaseTimer);releaseTimer=setTimeout(finishNavigation,280)}},{passive:true});
addEventListener('pointerdown',e=>{if(!e.target.closest('.main-nav a'))release()},{passive:true});addEventListener('wheel',release,{passive:true});addEventListener('touchstart',release,{passive:true});addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','PageDown','PageUp','Home','End',' '].includes(e.key))release()});
const restoreAnchor=()=>{const link=links.find(a=>a.hash===location.hash);if(link)link.click();else schedule()};addEventListener('atlas:ready',restoreAnchor);addEventListener('hashchange',restoreAnchor);links.forEach(a=>a.addEventListener('click',e=>{const section=$(a.hash);if(!section)return;e.preventDefault();clicked=section.id;activate(clicked);clearTimeout(releaseTimer);section.scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});history.replaceState(null,'',a.hash);releaseTimer=setTimeout(finishNavigation,1800)}));measure();update();
}

function initializeSectionAtmosphere(){
const boundaries=[...document.querySelectorAll('.atlas-section-transition')],visible=new Set(),motion=matchMedia('(prefers-reduced-motion: reduce)'),desktop=matchMedia('(min-width: 761px)');let queued=false;
const paint=()=>{queued=false;for(const el of boundaries){const y=visible.has(el)&&desktop.matches&&!motion.matches?Math.max(-24,Math.min(24,(innerHeight/2-el.getBoundingClientRect().top)*.055)):0;el.style.setProperty('--mist-shift',y+'px')}};
const schedule=()=>{if(!queued){queued=true;requestAnimationFrame(paint)}};
const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting)visible.add(entry.target);else visible.delete(entry.target)}schedule()},{rootMargin:'240px'});boundaries.forEach(el=>observer.observe(el));
addEventListener('scroll',()=>{if(desktop.matches&&!motion.matches&&visible.size)schedule()},{passive:true});addEventListener('resize',schedule,{passive:true});motion.addEventListener('change',schedule);desktop.addEventListener('change',schedule);schedule();
}

function sideTrips(){return `<aside class="journey-sidebar"><span class="eyebrow">BIBLIOTECA DE VIAGENS</span><h2>Para onde vamos?</h2><label class="sidebar-search"><span class="sr-only">Buscar viagem</span><input id="tripSearch" type="search" placeholder="Buscar destino ou viagem…"></label><div class="side-trip-list">${aviation.trips.map(t=>{const fs=aviation.flights.filter(f=>t.flightIds.includes(f.id));return `<button data-trip="${esc(t.id)}">${icon('plane')}<span><strong>${esc(t.name)}</strong><small>${fs.length} trechos · ${fs[0]?.year||'Ano a confirmar'}</small></span>${icon('arrow')}</button>`}).join('')}</div></aside>`}
const galleryState={q:'',iso:'',sort:'name',limit:6};
const topicState={type:'countries',q:'',limit:40};
function stadiumPicture(v){if(v.photoUrl&&/^(https:\/\/|data:image\/(jpeg|png|webp);base64,)/i.test(v.photoUrl))return {url:v.photoUrl,credit:v.photoUrl.startsWith('data:')?'Foto pessoal':'Foto cadastrada',source:v.photoUrl.startsWith('data:')?'':v.photoUrl};const p=findStadiumDetails(v)?.photo;return p?{...p,credit:p.author+' · '+p.license}:null}
function stadiumImage(v,loading='lazy'){const p=stadiumPicture(v);const position=Number.isFinite(Number(v.photoPosition))?Math.max(0,Math.min(100,Number(v.photoPosition))):52;return p?`<img src="${esc(p.url)}" alt="${esc(v.stadium)}" loading="${loading}" decoding="async" data-fallback="${esc(p.originalUrl||'')}" style="object-position:50% ${position}%">`:'<span class="stadium-photo-empty">'+icon('stadium')+'<span>Foto indisponível</span></span>'}
function heroStadium(){const v=stadiums.find(v=>norm(v.stadium).includes('bernabeu'))||stadiums.find(v=>v.photoUrl&&stadiumPicture(v))||stadiums.find(v=>stadiumPicture(v));return v?`<a class="hero-stadium-teaser" href="#stadiums">${norm(v.stadium).includes('bernabeu')?'<img src="assets/memories/memoria-11.webp" alt="Santiago Bernabéu, Madrid · foto pessoal" width="900" height="675" loading="eager" fetchpriority="high">':stadiumImage(v,'eager')}<span><small>EM DESTAQUE</small><strong>${esc(v.stadium)}</strong><span>${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''}</span></span>${icon('arrow')}</a>`:''}
function stadiumSection(){return `<section class="stadium-section" id="stadiums" aria-labelledby="stadiumGalleryTitle"><div class="section-title"><div><h2 id="stadiumGalleryTitle">Estádios</h2></div><button class="manager-section-button" data-manage="stadiums">Gerenciar coleção ${icon('arrow')}</button></div><div class="stadium-filters"><label>BUSCAR ESTÁDIO OU CIDADE<input id="stadiumSearch" type="search" placeholder="Ex.: Azteca, Santos, Buenos Aires…"></label><label>PAÍS<select id="stadiumCountry"><option value="">Todos os países</option>${countries.filter(c=>stadiums.some(v=>v.iso===c.iso)).map(c=>`<option value="${c.iso}">${esc(c.name)}</option>`).join('')}</select></label><label>ORDENAR<select id="stadiumSort"><option value="name">Nome · A–Z</option><option value="country">País</option><option value="visits">Mais visitados</option></select></label><button id="stadiumClear">Limpar filtros</button></div><p id="stadiumCount" class="stadium-count" role="status" aria-live="polite"></p><div class="stadium-gallery" id="stadiumGallery"></div><div class="stadium-more"><button class="outline-button" id="stadiumMore">Ver mais estádios ${icon('arrow')}</button><span id="stadiumShown"></span></div></section>`}
function filteredStadiums(){return visits.map((v,index)=>({...v,index})).filter(v=>v.stadium&&(!galleryState.iso||v.iso===galleryState.iso)&&norm([v.stadium,v.city,v.atlasLocality,v.country,v.club].join(' ')).includes(norm(galleryState.q))).sort((a,b)=>galleryState.sort==='country'?a.country.localeCompare(b.country,'pt')||a.stadium.localeCompare(b.stadium,'pt'):galleryState.sort==='visits'?(Math.max(1,Number(b.visitCount)||1)-Math.max(1,Number(a.visitCount)||1))||a.stadium.localeCompare(b.stadium,'pt'):a.stadium.localeCompare(b.stadium,'pt'))}
function renderGallery(){const fs=filteredStadiums(),shown=fs.slice(0,galleryState.limit);$('#stadiumCount').textContent=fs.length+' '+(fs.length===1?'estádio encontrado':'estádios encontrados');$('#stadiumGallery').innerHTML=shown.length?shown.map(v=>{const p=stadiumPicture(v);return `<article class="stadium-gallery-card"><button class="stadium-card-image" data-stadium="${v.index}" aria-label="Ver fotos e detalhes de ${esc(v.stadium)}">${stadiumImage(v)}<span class="stadium-country">${esc(v.country)}</span><span class="stadium-image-cta">Ver detalhes ${icon('arrow')}</span><span class="image-unavailable" hidden>Fotografia indisponível no momento</span></button><div class="stadium-card-body"><h3><button data-stadium="${v.index}">${esc(v.stadium)}</button></h3><p>${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''} · ${Math.max(1,Number(v.visitCount)||1)} ${Number(v.visitCount)>1?'visitas':'visita'}</p>${p?.source?`<a class="photo-credit" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Foto: ${esc(p.credit)} ↗</a>`:`<span class="photo-credit">${esc(p?.credit||'Acervo pessoal')}</span>`}</div></article>`}).join(''):'<p class="gallery-empty">Nenhum estádio encontrado. Tente outro nome ou limpe os filtros.</p>';$('#stadiumShown').textContent=fs.length?'Mostrando '+shown.length+' de '+fs.length+' estádios':'';$('#stadiumMore').hidden=shown.length>=fs.length;bindImageFallbacks($('#stadiumGallery'))}
function bindImageFallbacks(root){root.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{const fallback=img.dataset.fallback;if(fallback&&img.src!==fallback){img.dataset.fallback='';img.src=fallback;return}img.hidden=true;const label=img.parentElement.querySelector('.image-unavailable');if(label)label.hidden=false}))}
function dialogShell(){let d=$('#atlasDetail');if(!d){d=document.createElement('dialog');d.id='atlasDetail';d.className='atlas-detail';d.setAttribute('aria-labelledby','atlasDetailTitle');d.innerHTML='<button class="atlas-detail-close" aria-label="Fechar detalhes">×</button><div id="atlasDetailBody"></div>';document.body.append(d);d.querySelector('.atlas-detail-close').onclick=()=>d.close();d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();d.close()}});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})}return d}
function openStadium(index){const v=visits[index];if(!v?.stadium)return;const d=dialogShell(),p=stadiumPicture(v),games=Array.isArray(v.matches)?v.matches.filter(g=>g&&typeof g==='object'):[];$('#atlasDetailBody').innerHTML=`<div class="stadium-detail-photo">${stadiumImage(v,'eager')}<span class="image-unavailable" hidden>Fotografia indisponível no momento</span></div><div class="stadium-detail-body"><span class="eyebrow">${esc(v.country)} · ESTÁDIO</span><h2 id="atlasDetailTitle">${esc(v.stadium)}</h2><p class="detail-subtitle">${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''} · ${Math.max(1,Number(v.visitCount)||1)} ${Number(v.visitCount)>1?'visitas':'visita'}</p><div class="stadium-detail-facts">${v.club?`<div><small>CLUBE / EVENTO</small><strong>${esc(v.club)}</strong></div>`:''}${v.date?`<div><small>DATA DA VISITA</small><strong>${esc(v.date)}</strong></div>`:''}${games.length?`<div><small>JOGOS REGISTRADOS</small><strong>${games.length}</strong></div>`:''}</div>${v.notes?`<div class="detail-notes"><h3>Observações</h3><p>${esc(v.notes)}</p></div>`:''}${games.length?`<details class="stadium-games"><summary>Meus jogos neste estádio (${games.length})</summary>${games.map(g=>`<article><strong>${esc(g.homeTeam||'Mandante')} ${esc(g.homeScore??'—')} × ${esc(g.awayScore??'—')} ${esc(g.awayTeam||'Visitante')}</strong><p>${esc(g.date||'Data não informada')} · ${esc(g.competition||'')}</p>${g.notes?`<p>${esc(g.notes)}</p>`:''}</article>`).join('')}</details>`:''}${p?.source?`<a class="photo-credit" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Foto: ${esc(p.credit)} ↗</a>`:`<p class="photo-credit">${esc(p?.credit||'')}</p>`}${p?.licenseUrl?`<a class="photo-credit" href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">Licença: ${esc(p.license)}</a>`:''}<div class="detail-actions"><button class="gold-button" id="detailMap">Localizar no mapa ${icon('pin')}</button><button class="outline-button" data-edit-visit="${index}">Editar estádio ${icon('arrow')}</button></div></div>`;$('#detailMap').onclick=()=>{d.close();selectedPlaceScope=null;selectedFlight=null;selectedTrip='';$('#tripSelect').value='';$('#tripCurrentLabel').textContent='Todas as rotas';syncRouteControls();mapReturn=()=>$('#stadiums').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});$('#mapBack').textContent='Voltar aos estádios';$('#mapBack').hidden=false;const p=points.find(p=>p.index===index);if(!p){$('#mapCaption').textContent='Este estádio ainda não tem coordenadas cadastradas.';$('#explore').scrollIntoView({behavior:reduced?'auto':'smooth'});return}mapLayer='stadiums';document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layer===mapLayer)));update2d();update3d();if(view==='3d'&&globe)globe.pointOfView({lat:p.lat,lng:p.lng,altitude:.9},reduced?0:1000);else map.setView([p.lat,p.lng],12);$('#explore').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});place(p)};bindImageFallbacks($('#atlasDetailBody'));if(!d.open)d.showModal()}
function openTopic(type,query=''){if(type==='flights'){showFlights();if(query){flightState.q=query;renderFlights()}return}if(type==='stadiums'){$('#stadiums').scrollIntoView({behavior:reduced?'auto':'smooth'});return}topicState.type=type;topicState.q=query;topicState.limit=40;const names={countries:'Países visitados',cities:'Cidades exploradas',flights:'Meu histórico de voos'};const d=dialogShell();$('#atlasDetailBody').innerHTML=`<div class="topic-detail"><h2 id="atlasDetailTitle">${names[type]||'Meu Atlas'}</h2>${type==='cities'?'<div class="manager-section-actions"><button class="outline-button" data-manager-new="city">＋ Incluir cidade</button><button class="outline-button" data-manage="cities">Gerenciar cidades</button></div>':''}<label class="topic-search"><span class="sr-only">Buscar neste tópico</span><input id="topicSearch" type="search" placeholder="${type==='flights'?'Buscar rota, companhia, voo ou ano…':'Buscar cidade ou país…'}" value="${esc(query)}"></label><p id="topicCount" role="status" aria-live="polite"></p><div id="topicRows"></div><button class="outline-button" id="topicMore">Carregar mais</button>${type==='flights'?'<a class="topic-edit" href="#journeys">Explorar registros de voos</a>':''}</div>`;$('#topicSearch').oninput=e=>{topicState.q=e.target.value;topicState.limit=40;renderTopic()};$('#topicMore').onclick=()=>{topicState.limit+=40;renderTopic()};renderTopic();if(!d.open)d.showModal()}
function countryCities(iso){const groups=new Map();visits.forEach((v,index)=>{if(v.iso.toUpperCase()!==iso.toUpperCase())return;const key=norm(v.city).trim();if(!groups.has(key))groups.set(key,{name:v.city,stadiums:[]});const city=groups.get(key);if(v.stadium&&!city.stadiums.some(s=>norm(s.stadium).trim()===norm(v.stadium).trim()))city.stadiums.push({...v,index})});return [...groups.values()].sort((a,b)=>a.name.localeCompare(b.name,'pt')).map(city=>({...city,stadiums:city.stadiums.sort((a,b)=>a.stadium.localeCompare(b.stadium,'pt'))}))}
function countryCityMarkup(iso,onMap=false,cityKey=''){return `<div class="country-city-list${onMap?' country-city-list--map':''}">${countryCities(iso).filter(city=>!cityKey||norm(city.name)===cityKey).map(city=>`<section class="country-city"><h4>${esc(city.name)}</h4>${city.stadiums.length?`<ul>${city.stadiums.map(v=>`<li>${onMap?`<button type="button" data-country-stadium="${v.index}">${esc(v.stadium)}${icon('arrow')}</button>`:esc(v.stadium)}${v.atlasLocality?`<small>${esc(v.atlasLocality)}</small>`:''}</li>`).join('')}</ul>`:'<p>Nenhum estádio registrado nesta cidade.</p>'}</section>`).join('')}</div>`}
function renderTopic(){const q=norm(topicState.q);let rows=[];if(topicState.type==='countries')rows=countries.map(c=>({...c,cities:countryCities(c.iso)})).filter(c=>norm([c.name,...c.cities.flatMap(city=>[city.name,...city.stadiums.map(v=>v.stadium)])].join(' ')).includes(q)).map(c=>`<details class="topic-country-group"${q?' open':''}><summary class="topic-country">${countryCodes[c.iso]?`<img src="assets/flags/${countryCodes[c.iso]}.svg" alt="" width="34" height="25">`:icon('globe')}<span><strong>${esc(c.name)}</strong><small>${c.cities.length} ${c.cities.length===1?'cidade':'cidades'} · ${c.cities.reduce((n,city)=>n+city.stadiums.length,0)} ${c.cities.reduce((n,city)=>n+city.stadiums.length,0)===1?'estádio':'estádios'}</small></span><span class="country-disclosure" aria-hidden="true">${icon('arrow')}</span></summary><div class="topic-country-content"><div class="country-content-heading"><h3>Cidades e estádios</h3><button type="button" class="outline-button country-map-link" data-topic-country="${esc(c.iso)}">Ver no mapa ${icon('pin')}</button></div>${countryCityMarkup(c.iso)}</div></details>`);else if(topicState.type==='cities')rows=[...new Map(visits.map(v=>[v.iso+'|'+norm(v.city),v])).values()].sort((a,b)=>a.city.localeCompare(b.city,'pt')).filter(v=>norm(v.city+' '+v.country).includes(q)).map(v=>`<button class="topic-country" data-topic-city="${esc(v.iso+'|'+norm(v.city))}">${icon('pin')}<span><strong>${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''}</strong><small>${esc(v.country)} · ${stadiums.filter(s=>s.iso===v.iso&&norm(s.city)===norm(v.city)).length} estádios</small></span>${icon('arrow')}</button>`);else rows=aviation.flights.filter(f=>norm([f.origin,f.destination,f.originCity,f.destinationCity,f.code,f.carrier,f.dayMonth,f.year].join(' ')).includes(q)).map(f=>`<button class="topic-flight" data-flight-detail="${esc(f.id)}"><span><strong>${esc(f.origin||f.originCity)} → ${esc(f.destination||f.destinationCity)}</strong><small>${esc(f.originCity)} → ${esc(f.destinationCity)}</small></span><span>${esc(f.carrier||'Companhia não informada')}<small>${esc(f.dayMonth)} ${f.year||'Ano não informado'}</small></span>${icon('arrow')}</button>`);$('#topicCount').textContent=rows.length+' '+(topicState.type==='flights'?(rows.length===1?'registro':'registros'):topicState.type==='cities'?(rows.length===1?'cidade':'cidades'):(rows.length===1?'país':'países'));$('#topicRows').innerHTML=rows.slice(0,topicState.limit).join('')||'<p>Nenhum resultado para esta busca.</p>';$('#topicMore').hidden=rows.length<=topicState.limit}
function openFlight(id){const f=aviation.flights.find(f=>f.id===id);if(!f)return;const d=dialogShell();$('#atlasDetailBody').innerHTML=`<div class="topic-detail"><button class="topic-back" id="backFlights">← Voltar aos voos</button><button class="outline-button manager-detail-edit" data-edit-flight="${esc(f.id)}">Editar voo</button><span class="eyebrow">DETALHES DO VOO</span><h2 id="atlasDetailTitle">${esc(f.origin||f.originCity)} → ${esc(f.destination||f.destinationCity)}</h2><p>${esc(f.originCity)} → ${esc(f.destinationCity)}</p><div class="stadium-detail-facts">${[['COMPANHIA',f.carrier||'Não informada'],['VOO',f.code||'Não informado'],['DATA',flightDate(f)],['DISTÂNCIA DIRETA',f.km?num(f.km)+' km':'Não calculada']].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div>${f.notes?`<details class="stadium-games"><summary>Notas deste registro</summary><p>${esc(f.notes)}</p></details>`:''}</div>`;$('#backFlights').onclick=()=>{d.close();$('#flightCollection').hidden=false;renderFlights();$('#flightCollection').scrollIntoView({behavior:reduced?'auto':'smooth'})};$('#atlasDetailBody .topic-detail').insertAdjacentHTML('beforeend',`<p class="detail-subtitle">${esc(durationLabel(f))}</p>${aviationHasRoute(f)?`<button class="gold-button" data-flight-map="${esc(f.id)}">Ver rota no mapa ${icon('pin')}</button>`:''}`);if(!d.open)d.showModal()}
function initializeCollections(){renderGallery();bindImageFallbacks($('.immersive-intro'));$('#stadiumSearch').oninput=e=>{galleryState.q=e.target.value;galleryState.limit=6;renderGallery()};$('#stadiumCountry').onchange=e=>{galleryState.iso=e.target.value;galleryState.limit=6;renderGallery()};$('#stadiumSort').onchange=e=>{galleryState.sort=e.target.value;renderGallery()};$('#stadiumClear').onclick=()=>{Object.assign(galleryState,{q:'',iso:'',sort:'name',limit:6});$('#stadiumSearch').value='';$('#stadiumCountry').value='';$('#stadiumSort').value='name';renderGallery()};$('#stadiumMore').onclick=()=>{galleryState.limit+=12;renderGallery()};const versions=document.querySelector('.review-bar nav');if(versions){versions.setAttribute('aria-label','Versões da opção 01');versions.innerHTML='<a href="conceito-1-v1.html">V1</a><a href="atlas-01-v2.html" aria-current="page">V2</a>'}document.addEventListener('click',e=>{const topic=e.target.closest('[data-topic]');if(topic){e.preventDefault();openTopic(topic.dataset.topic)}const stadium=e.target.closest('[data-stadium]');if(stadium)openStadium(Number(stadium.dataset.stadium));const countryStadium=e.target.closest('[data-country-stadium]');if(countryStadium){const index=Number(countryStadium.dataset.countryStadium),p=points.find(p=>p.index===index);if(p){if(view==='3d'&&globe)globe.pointOfView({lat:p.lat,lng:p.lng,altitude:.65},reduced?0:900);else map.setView([p.lat,p.lng],13);place(p)}else openStadium(index)}const city=e.target.closest('[data-topic-city]');if(city){$('#atlasDetail').close();const [iso,name]=city.dataset.topicCity.split('|');focusCountry(iso,name)}const country=e.target.closest('[data-topic-country]');if(country){$('#atlasDetail').close();focusCountry(country.dataset.topicCountry)}const flight=e.target.closest('[data-flight-detail]');if(flight)openFlight(flight.dataset.flightDetail)})}
function initializeRails(){const tracks=[...document.querySelectorAll('.auto-rail')].map(el=>({el,paused:reduced,visible:false,hover:false,focus:false,drag:false,moved:false,direction:1,resumeAt:0}));const railObserver=new IntersectionObserver(entries=>{for(const entry of entries){const t=tracks.find(t=>t.el===entry.target);if(t)t.visible=entry.isIntersecting}},{rootMargin:'100px'});tracks.forEach(t=>railObserver.observe(t.el));for(const t of tracks){const control=t.el.closest('.section-rail')?.querySelector('[data-rail-motion]');if(!control)continue;const name=t.el.id==='competitionRail'?'das competições':t.el.id==='carrierRail'?'das companhias aéreas':'dos países';const label=()=>{control.innerHTML=icon(t.paused?'play':'pause')+'<span>'+(t.paused?'Ativar':'Pausar')+'</span>';control.setAttribute('aria-pressed',String(t.paused));control.setAttribute('aria-label',(t.paused?'Ativar':'Pausar')+' movimento '+name);};label();control.onclick=()=>{t.paused=!t.paused;t.position=t.el.scrollLeft;label();};}for(const t of tracks){const el=t.el;el.addEventListener('mouseenter',()=>t.hover=true);el.addEventListener('mouseleave',()=>t.hover=false);el.addEventListener('focusin',()=>t.focus=true);el.addEventListener('focusout',e=>{if(!el.contains(e.relatedTarget))t.focus=false});el.addEventListener('pointerdown',e=>{t.resumeAt=performance.now()+3500;if(e.pointerType!=='mouse'||e.button!==0)return;t.drag=true;t.moved=false;t.x=e.clientX;t.scroll=el.scrollLeft});el.addEventListener('pointermove',e=>{if(!t.drag)return;const dx=e.clientX-t.x;if(Math.abs(dx)>4){t.moved=true;el.classList.add('dragging');if(!el.hasPointerCapture(e.pointerId))el.setPointerCapture(e.pointerId);el.scrollLeft=t.scroll-dx;e.preventDefault()}});const finish=e=>{if(!t.drag)return;t.drag=false;el.classList.remove('dragging');if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);t.resumeAt=performance.now()+3500;setTimeout(()=>t.moved=false,100)};el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',finish);el.addEventListener('click',e=>{if(t.moved){e.preventDefault();e.stopPropagation()}},true);el.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();el.scrollLeft+=(e.key==='ArrowRight'?1:-1)*110;t.resumeAt=performance.now()+3500}})}let previous=performance.now();function tick(now){const dt=Math.min(50,now-previous);previous=now;for(const t of tracks){if(t.paused||!t.visible||document.hidden||t.hover||t.focus||t.drag||now<t.resumeAt){t.position=t.el.scrollLeft;continue}const max=t.el.scrollWidth-t.el.clientWidth;if(max<1)continue;t.position=Math.max(0,Math.min(max,(t.position??t.el.scrollLeft)+t.direction*dt*.025));t.el.scrollLeft=t.position;if(t.position>=max-1)t.direction=-1;else if(t.position<=0)t.direction=1}requestAnimationFrame(tick)}requestAnimationFrame(tick)}

let content='';
if(layout===1)content=`<main id="main"><div class="immersive-shell"><section class="immersive-intro"><h1>Viagens.<br><em>Futebol.</em></h1><p>Países visitados, estádios e voos registrados.</p><a class="gold-button" href="#stadiums">Ver estádios ${icon('arrow')}</a>${heroStadium()}<div class="intro-coordinate"><i></i> SÃO PAULO · BRASIL</div></section>${mapMarkup}</div>${stats()}${stadiumSection()}${passport()}${recent()}${memories()}</main>`;
if(layout===2)content=`<main id="main"><section class="editorial-hero"><img class="editorial-backdrop" src="assets/editorial/istanbul.webp" alt="Panorama de Istambul e do Bósforo" width="1920" height="1440"><div class="editorial-copy"><span class="eyebrow">VIAGENS, FUTEBOL E TUDO ENTRE ELES</span><h1>Alguns lugares<br>mudam a nossa<br><em>história.</em></h1><p>Meu Atlas é sobre esses encontros.<br>Com o mundo. Com o jogo. Com a vida.</p><a class="gold-button" href="#explore">Explorar minhas memórias ${icon('arrow')}</a></div><div class="editorial-destination"><span>EM DESTAQUE</span><strong>Istambul, Turquia</strong>${credit('istanbul')}</div><span class="hero-index">01 <i></i> DIÁRIO DE BORDO</span></section>${passport()}${stats()}${memories()}${mapMarkup}${recent()}</main>`;
if(layout===3)content=`<main id="main"><section class="dashboard-heading"><div><span class="eyebrow">MEU ATLAS PESSOAL</span><h1>Seu mundo,<br><em>por outro ângulo.</em></h1></div><p>Cidades que conheci. Caminhos que percorri.<br>Histórias que quero guardar.</p><a class="outline-button" href="#main">Abrir meu Atlas ${icon('arrow')}</a></section>${stats()}<div class="dashboard-layout">${sideTrips()}${mapMarkup}</div>${passport()}${recent()}${memories()}</main>`;
$('#previewApp').innerHTML=nav+(demo?'<p class="data-mode is-demo">Dados demonstrativos. Use Gerenciar meu Atlas para começar ou <button class="manager-inline-link" data-manager-import>importe seu backup</button> neste navegador.</p>':'')+content+`<footer class="preview-footer"><a class="wordmark gr-wordmark" href="#main" aria-label="Gabriel Rodriguez — início"><img src="assets/brand/gabriel-rodriguez.svg?v=1" alt="Gabriel Rodriguez" width="494" height="197" loading="lazy"></a><span>Estádios · Voos · Memórias</span><details><summary>Créditos de imagens e bibliotecas</summary><p>Fotos de referência: Wikimedia Commons. Fotos pessoais: acervo de Gabriel Rodriguez.</p>${Object.entries(photoCredits).map(([id,c])=>`<a href="${c.source}" target="_blank" rel="noopener noreferrer">${id}: ${esc(c.author)} · ${c.license} ↗</a>`).join('')}<p>Globe.gl: MIT · Bandeiras: flag-icons, MIT · Ícones de marcas: Simple Icons, CC0. Marcas pertencem aos seus titulares.</p><a href="DESIGN-CREDITS.md">Fontes e licenças completas ↗</a><a href="COMPETITION-LOGOS.md">Fontes dos logotipos das competições ↗</a><a href="AIRLINE-LOGOS.md">Fontes dos logotipos das companhias ↗</a></details><button class="manager-inline-link" data-manager-import>Importar / restaurar backup ${icon('arrow')}</button></footer>`;
